  evidence: Evidence[];
  /** Revision-only: the Risk Officer's verdict. Present ⇒ this is the revision pass. */
  riskReport?: RiskReport | null;
  /** Revision-only: the Bear/Critic's case. */
  bearCase?: BearCase | null;
