// evidence — not its ID or notional. `finalize` computes the notional from NAV
// (so it always satisfies the risk engine's amount≈weight×NAV check) and
// assigns the ID.
const ProposedActionDraftSchema = ProposedActionSchema.omit({
  id: true,
  amount: true,
});

