2	import type { Claim } from "./evidence";
3	import { PORTFOLIO_LEVEL_ACTION_ID } from "./portfolio";
4	import type { DecisionReceipt } from "./receipts";
5	
6	/**
7	 * Referential-integrity helpers for evidence.
8	 *
9	 * The core invariant of Sonar AI: every material graph edge and thesis claim
10	 * resolves to a known evidence record. A model output is invalid until this
11	 * holds. These pure functions let both the contract tests and the orchestrator's
12	 * evidence gate enforce it the same way.
13	 */
14	
15	function claimEvidenceIds(claims: readonly Claim[] | undefined): string[] {
16	  return (claims ?? []).flatMap((c) => c.evidenceIds);
17	}
18	
19	/**
20	 * Every evidence ID referenced anywhere in the committee state — events, graph
21	 * nodes and edges, proposed actions, agent claims, and activities.
22	 */
23	export function collectReferencedEvidenceIds(
24	  state: InvestmentCommitteeState,
25	): Set<string> {
26	  const ids: string[] = [];
27	
28	  for (const event of state.materialEvents) ids.push(...event.evidenceIds);
29	  for (const node of state.graph.nodes) ids.push(...node.evidenceIds);
30	  for (const edge of state.graph.edges) ids.push(...edge.evidenceIds);
31	  for (const action of state.proposedActions) ids.push(...action.evidenceIds);
32	  for (const report of state.fundamentalReports)
33	    ids.push(...claimEvidenceIds(report.claims));
34	  ids.push(...claimEvidenceIds(state.marketContext?.claims));
35	
36	  for (const rec of [state.proposal, state.finalRecommendation]) {
37	    if (!rec) continue;
38	    ids.push(...claimEvidenceIds(rec.bull));
39	    ids.push(...claimEvidenceIds(rec.context));
40	    ids.push(...claimEvidenceIds(rec.bear));
41	    for (const action of rec.actions) ids.push(...action.evidenceIds);
42	  }
43	
44	  ids.push(...claimEvidenceIds(state.bearCase?.claims));
45	  for (const activity of state.activities) ids.push(...activity.evidenceIds);
46	
47	  return new Set(ids);
48	}
49	
50	/**
51	 * Referenced evidence IDs that do not resolve to a record in `state.evidence`.
52	 * An empty array means the state is referentially sound.
53	 */
54	export function findDanglingEvidenceIds(
55	  state: InvestmentCommitteeState,
56	): string[] {
57	  const known = new Set(state.evidence.map((e) => e.id));
58	  const referenced = collectReferencedEvidenceIds(state);
59	  return [...referenced].filter((id) => !known.has(id));
60	}
61	
62	// ── Action referential integrity ────────────────────────────────────────────
63	
64	/**
65	 * Every action ID a risk check can legitimately point at: the initial proposal,
66	 * the revised recommendation, the flattened proposed actions, and any applied
67	 * order. A risk check may also use the {@link PORTFOLIO_LEVEL_ACTION_ID}
68	 * sentinel for portfolio-wide breaches.
69	 */
70	export function collectKnownActionIds(
71	  state: InvestmentCommitteeState,
72	): Set<string> {
73	  const ids = new Set<string>();
74	  for (const a of state.proposal?.actions ?? []) ids.add(a.id);
75	  for (const a of state.finalRecommendation?.actions ?? []) ids.add(a.id);
76	  for (const a of state.proposedActions) ids.add(a.id);
77	  for (const o of state.appliedOrders) ids.add(o.actionId);
78	  return ids;
79	}
80	
81	/**
82	 * Risk-check `actionId`s that resolve to no known action (excluding the
83	 * portfolio-level sentinel). Guards the failure the evidence gate cannot see: a
84	 * check pointing at an action that was revised away.
85	 */
86	export function findDanglingActionIds(
87	  state: InvestmentCommitteeState,
88	): string[] {
89	  const known = collectKnownActionIds(state);
90	  const checks = [...(state.riskReport?.checks ?? []), ...state.riskChecks];
91	  return checks
92	    .map((c) => c.actionId)
93	    .filter((id) => id !== PORTFOLIO_LEVEL_ACTION_ID && !known.has(id));
94	}
