298	        message: `Applied ${state.appliedOrders.length} paper orders after approval.`,
299	        refId: `rcpt_${state.run.id}`,
300	      });
301	    }
302	    const completedAt = isoAfter(decision.decidedAt, 3);
303	    state.run = { ...state.run, completedAt };
304	    const receiptId = `rcpt_${state.run.id}`;
305	    state.receipt = {
306	      id: receiptId,
307	      runId: state.run.id,
308	      createdAt: completedAt,
309	      event: state.materialEvents[0] ?? null,
310	      portfolioBefore: state.portfolioSnapshot,
311	      portfolioAfter: execution.portfolio,
312	      proposal: state.proposal,
313	      recommendation: state.finalRecommendation!,
314	      riskReport: state.riskReport!,
315	      bearCase: state.bearCase,
316	      userDecision: state.userDecision,
317	      appliedOrders: state.appliedOrders,
318	      report: state.report,
319	      evidence: state.evidence,
320	    };
321	    transition(state, "complete", decision.decision === "approved" ? "Decision receipt completed." : "Decision rejected; no paper actions applied.");
322	    return validateState(state);
323	  }
324	
325	  private applyApprovedActions(state: InvestmentCommitteeState, appliedAt: string) {
326	    if (!state.finalRecommendation || !state.marketSnapshot) {
327	      throw new Error("Approved action requires final recommendation and market snapshot.");
328	    }
329	    if (state.riskReport?.hardBlocks.length) {
330	      throw new Error("Approved action cannot bypass deterministic risk hard block.");
331	    }
332	    return applyPaperActions({
333	      portfolio: state.portfolioSnapshot,
334	      actions: state.finalRecommendation.actions,
335	      marketSnapshot: state.marketSnapshot,
336	      appliedAt,
337	    });
338	  }
339	}
340	
341	async function runAgent<TContext, TOutput>(
342	  definition: AgentDef<TContext, TOutput>,
343	  context: TContext,
344	  runner: AgentRunner,
345	): Promise<TOutput> {
346	  const result = await runner.run(definition, context);
347	  const parsed = definition.outputSchema.safeParse(result.output);
348	  if (!parsed.success) {
349	    throw new Error(`${definition.stage} output failed schema validation.`);
350	  }
351	  return parsed.data;
352	}
353	
354	async function runFinalizedAgent<TContext, TDraft, TOutput>(
355	  agent: Agent<TContext, TDraft, TOutput>,
356	  context: TContext,
357	  runner: AgentRunner,
358	): Promise<TOutput> {
359	  const draft = await runAgent(agent.def, context, runner);
360	  return agent.finalize(draft, context);
361	}
362	
363	function pendingStages(runId: string): StageRecord[] {
364	  return AGENT_STAGES.map((stage) => ({
365	    runId,
366	    stage,
367	    status: "pending",
368	    startedAt: null,
369	    completedAt: null,
370	    outputId: null,
371	  }));
372	}
373	
374	function markStageRunning(state: InvestmentCommitteeState, stage: AgentStage, startedAt: string): void {
375	  const record = stageRecord(state, stage);
376	  record.status = "running";
377	  record.startedAt = startedAt;
378	  record.completedAt = null;
379	  record.outputId = null;
380	}
381	
382	function markStageComplete(state: InvestmentCommitteeState, stage: AgentStage, completedAt: string, outputId: string | null): void {
383	  const record = stageRecord(state, stage);
384	  record.status = "complete";
385	  record.completedAt = completedAt;
386	  record.outputId = outputId;
387	}
388	
389	function markStageFailed(state: InvestmentCommitteeState, stage: AgentStage, completedAt: string, note: string): void {
390	  const record = stageRecord(state, stage);
391	  record.status = "failed";
392	  record.completedAt = completedAt;
393	  record.note = note;
394	}
395	
396	function stageRecord(state: InvestmentCommitteeState, stage: AgentStage): StageRecord {
397	  const record = state.stages.find((candidate) => candidate.stage === stage);
398	  if (!record) throw new Error(`Missing stage record for "${stage}".`);
399	  return record;
400	}

