1	import {
2	  AGENT_STAGES,
3	  InvestmentCommitteeStateSchema,
4	  UserDecisionSchema,
5	  type ActivityEvent,
6	  type AgentStage,
7	  type Evidence,
8	  type FundamentalReport,
9	  type InvestmentCommitteeState,
10	  type RiskReport,
11	  type StageRecord,
12	  type UserDecision,
13	} from "@sonar-ai/core";
14	import type { AlpacaOrderResponse, AlpacaPaperOrderRequest } from "@sonar-ai/core/alpaca";
15	import { type InstrumentStats, type StressScenario } from "@sonar-ai/risk-engine";
16	import { bearCritic } from "./agents/bear-critic";
17	import { fundamentalAnalyst } from "./agents/fundamental-analyst";
18	import { marketContextAnalyst } from "./agents/market-context";
19	import { portfolioManager } from "./agents/portfolio-manager";
20	import { reportWriter } from "./agents/report-writer";
21	import { runRiskOfficer } from "./agents/risk-officer";
22	import type { Agent } from "./agents/types";
23	import {
24	  buildBearCriticContext,
25	  buildFundamentalContext,
26	  buildMarketContext,
27	  buildPortfolioManagerContext,
28	  buildReportWriterContext,
29	} from "./context";
30	import { checkEvidenceGate, checkHumanApprovalGate, checkRiskGate } from "./gates";
31	import { applyPaperActions } from "./trader";
32	import type { AgentDef, AgentRunner } from "./runner/types";
33	
34	export interface AnalysisOrchestratorOptions {
35	  runner: AgentRunner;
36	  instrumentStats?: InstrumentStats;
37	  stressScenarios?: readonly StressScenario[];
38	  /** Live mode injects AlpacaPaperClient; absent means offline ledger mode. */
39	  alpacaClient?: { submitPaperOrder(input: AlpacaPaperOrderRequest): Promise<AlpacaOrderResponse> };
40	}
41	
42	export interface AnalysisRunInput {
43	  /** An idle, validated state containing inputs, evidence, and graph. */
44	  state: InvestmentCommitteeState;
45	  /** Optional decision for callers that can provide approval in the same request. */
46	  userDecision?: UserDecision;
47	}
48	
49	const STAGE_OFFSETS: Record<AgentStage, number> = {
50	  fundamental_analyst: 60,
51	  market_context: 60,
52	  portfolio_manager: 240,
53	  risk_officer: 270,
54	  bear_critic: 300,
55	  report_writer: 360,
56	};
57	
58	const ALLOWED_TRANSITIONS: Record<InvestmentCommitteeState["phase"], readonly InvestmentCommitteeState["phase"][]> = {
59	  idle: ["observing"],
60	  observing: ["tracing", "blocked"],
61	  tracing: ["proposing", "blocked"],
62	  proposing: ["challenging", "awaiting_approval", "blocked"],
63	  challenging: ["awaiting_approval", "blocked"],
64	  awaiting_approval: ["executing", "complete", "blocked"],
65	  executing: ["complete", "blocked"],
66	  blocked: [],
67	  complete: [],
68	};
69	
70	/**
71	 * Code-owned, linear committee runner. It is intentionally boring: explicit
72	 * stage order, no autonomous loop, no agent-to-agent calls, fixed timestamps,
73	 * and one human gate before paper-ledger mutation.
74	 */
75	export class AnalysisOrchestrator {
76	  constructor(private readonly options: AnalysisOrchestratorOptions) {}
77	
78	  async run(input: AnalysisRunInput): Promise<InvestmentCommitteeState> {
79	    const state = InvestmentCommitteeStateSchema.parse(structuredClone(input.state));
80	    const researchRunner = withEvidenceLedger(this.options.runner, state);
81	    if (state.phase !== "idle") {
82	      throw new Error(`AnalysisOrchestrator.run requires idle phase, got "${state.phase}".`);
83	    }
84	
85	    if (state.candidateUniverse.length === 0) throw new Error("Tradable candidate universe is empty.");
86	
87	    state.stages = pendingStages(state.run.id);
88	    let activeStage: AgentStage | undefined;
89	
90	    const executeStage = async <T>(
91	      stage: AgentStage,
92	      fn: () => Promise<T>,
93	      outputId: (output: T) => string | null,
94	    ): Promise<T> => {
95	      activeStage = stage;
96	      markStageRunning(state, stage, stageTime(state, stage));
97	      try {
98	        const output = await fn();
99	        markStageComplete(state, stage, stageTime(state, stage, 30), outputId(output));
100	        activeStage = undefined;
101	        return output;
102	      } catch (error) {
103	        throw new Error(`${stage} failed: ${error instanceof Error ? error.message : String(error)}`);
104	      }
105	    };
106	
107	    try {
108	      transition(state, "observing", "Committee run started.");
109	      transition(state, "tracing", "Research stages received isolated evidence packs.");
110	
111	      // Discovery runs first. Agents choose companies; user supplies risk preferences only.
112	      const marketContext = await executeStage(
113	        "market_context",
114	        () => runFinalizedAgent(
115	          marketContextAnalyst,
116	          buildMarketContext(state, state.candidateUniverse),
117	          researchRunner,
118	        ),
119	        (output) => output.id,
120	      );
121	      state.marketContext = marketContext;
122	
123	      const bySymbol = new Map(state.candidateUniverse.map((instrument) => [instrument.symbol.toUpperCase(), instrument]));
124	      const selectedInstruments = marketContext.candidateOpportunities.map((candidate) => {
125	        const instrument = bySymbol.get(candidate.symbol.toUpperCase());
126	        if (!instrument) throw new Error(`Cala candidate "${candidate.symbol}" is not in Alpaca tradable universe.`);
127	        return instrument;
128	      });
129	      if (selectedInstruments.length === 0) throw new Error("Cala returned no tradable investment candidates.");
130	      if (new Set(selectedInstruments.map((instrument) => instrument.id)).size !== selectedInstruments.length) {
131	        throw new Error("Cala returned duplicate investment candidates.");
132	      }
133	
134	      // Serial by design. Stable stage order makes replay independent of promise
135	      // scheduling while keeping both contexts isolated.
136	      const fundamentalReports: FundamentalReport[] = [];
137	      for (const instrument of selectedInstruments) {
138	        const report = await executeStage(
139	          "fundamental_analyst",
140	          () => runFinalizedAgent(
141	            fundamentalAnalyst,
142	            buildFundamentalContext(state, instrument),
143	            researchRunner,
144	          ),
145	          (output) => output.id,
146	        );
147	        fundamentalReports.push(report);
148	      }
149	      state.fundamentalReports = fundamentalReports;
150	
151	      const researchGate = checkEvidenceGate(state);
152	      if (!researchGate.ok) {
153	        return block(
154	          state,
155	          `Evidence gate failed: ${[...researchGate.danglingEvidenceIds, ...researchGate.danglingActionIds].join(", ")}.`,
156	        );
157	      }
158	
159	      transition(state, "proposing", "Research complete; Portfolio Manager is forming a proposal.");
160	      const proposal = await executeStage(
161	        "portfolio_manager",
162	        () => runFinalizedAgent(
163	          portfolioManager,
164	          buildPortfolioManagerContext(state, selectedInstruments, fundamentalReports, marketContext, { mode: "proposal" }),
165	          researchRunner,
166	        ),
167	        (output) => output.id,
168	      );
169	      if (proposal.revision !== 0) throw new Error("Initial Portfolio Manager output must have revision 0.");
170	      state.proposal = proposal;
171	      state.proposedActions = proposal.actions;
172	
173	      const proposalGate = checkEvidenceGate(state);
174	      if (!proposalGate.ok) {
175	        return block(
176	          state,
177	          `Evidence gate failed: ${[...proposalGate.danglingEvidenceIds, ...proposalGate.danglingActionIds].join(", ")}.`,
178	        );
179	      }
180	
181	      const proposalRisk = await executeStage(
182	        "risk_officer",
183	        async () => runRiskOfficer({
184	          portfolio: state.portfolioSnapshot,
185	          mandate: state.mandate,
186	          actions: proposal.actions,
187	          instruments: state.candidateUniverse,
188	          ...(this.options.instrumentStats ? { instrumentStats: this.options.instrumentStats } : {}),
189	          ...(this.options.stressScenarios ? { stressScenarios: this.options.stressScenarios } : {}),
190	          reportId: `rrp_${state.run.id}`,
191	        }),
192	        (output) => output.id,
193	      );
194	      state.riskReport = proposalRisk;
195	      state.riskChecks = proposalRisk.checks;
196	
197	      const riskGate = checkRiskGate(proposalRisk);
198	      if (!riskGate.ok) return block(state, riskGate.reason!);
199	
200	      transition(state, "challenging", "Proposal passed deterministic checks; Bear/Critic is challenging it.");
201	      const bearCase = await executeStage(
202	        "bear_critic",
203	        () => runFinalizedAgent(
204	          bearCritic,
205	          buildBearCriticContext(proposal, fundamentalReports, marketContext, proposalRisk, state.evidence),
206	          researchRunner,
207	        ),
208	        (output) => output.id,
209	      );
210	      if (bearCase.targetRecommendationId !== proposal.id) {
211	        throw new Error("Bear/Critic output targets a different recommendation.");
212	      }
213	      state.bearCase = bearCase;
214	
215	      const revision = await executeStage(
216	        "portfolio_manager",
217	        () => runFinalizedAgent(
218	          portfolioManager,
219	          buildPortfolioManagerContext(state, selectedInstruments, fundamentalReports, marketContext, {
220	            mode: "revision",
221	            proposal,
222	            riskReport: proposalRisk,
223	            bearCase,
224	          }),
225	          researchRunner,
226	        ),
227	        (output) => output.id,
228	      );
229	      if (revision.revision !== 1) throw new Error("Post-critique Portfolio Manager output must have revision 1.");
230	
231	      const revisionGate = checkEvidenceGate({ ...state, finalRecommendation: revision, proposedActions: revision.actions });
232	      if (!revisionGate.ok) {
233	        return block(
234	          state,
235	          `Evidence gate failed: ${[...revisionGate.danglingEvidenceIds, ...revisionGate.danglingActionIds].join(", ")}.`,
236	        );
237	      }
238	
239	      // Re-check revised actions with deterministic code. A model cannot use a
240	      // revision to bypass a limit that the first risk pass enforced.
241	      const finalRisk = runRiskOfficer({
242	        portfolio: state.portfolioSnapshot,
243	        mandate: state.mandate,
244	        actions: revision.actions,
245	        instruments: state.candidateUniverse,
246	        ...(this.options.instrumentStats ? { instrumentStats: this.options.instrumentStats } : {}),
247	        ...(this.options.stressScenarios ? { stressScenarios: this.options.stressScenarios } : {}),
248	        reportId: `rrp_${state.run.id}`,
249	      });
250	      if (finalRisk.hardBlocks.length > 0) return block(state, checkRiskGate(finalRisk).reason!);
251	
252	      state.finalRecommendation = revision;
253	      state.proposedActions = revision.actions;
254	      // Preserve the first risk report when revision is the deterministic,
255	      // risk-adjusted allocation. Otherwise expose final verification output.
256	      state.riskReport = sameComparison(proposalRisk, finalRisk) ? proposalRisk : finalRisk;
257	      state.riskChecks = state.riskReport.checks;
258	      transition(state, "awaiting_approval", "Recommendation is ready for explicit human approval.");
259	
260	      return input.userDecision ? this.approve(state, input.userDecision) : validateState(state);
261	    } catch (error) {
262	      if (activeStage) markStageFailed(state, activeStage, stageTime(state, activeStage, 30), errorMessage(error));
263	      return block(state, errorMessage(error));
264	    }
265	  }
266	
267	  async approve(
268	    stateInput: InvestmentCommitteeState,
269	    decisionInput: UserDecision,
270	  ): Promise<InvestmentCommitteeState> {
271	    const state = InvestmentCommitteeStateSchema.parse(structuredClone(stateInput));
272	    const decision = UserDecisionSchema.parse(decisionInput);
273	    const gate = checkHumanApprovalGate(state, decision);
274	    if (!gate.ok) throw new Error(gate.reason!);
275	
276	    state.userDecision = decision;
277	    const appliedAt = isoAfter(decision.decidedAt, 2);
278	    const execution = decision.decision === "approved"
279	      ? await this.applyApprovedActions(state, appliedAt)
280	      : { orders: [], portfolio: state.portfolioSnapshot };
281	
282	    // Writer runs after decision and before ledger state is committed. It can
283	    // describe the outcome but has no authority to change actions.
284	    markStageRunning(state, "report_writer", isoAfter(decision.decidedAt, 1));
285	    try {
286	      const writerState = {
287	        ...state,
288	        portfolioAfter: execution.portfolio,
289	        appliedOrders: execution.orders,
290	      };
291	      const report = await runFinalizedAgent(reportWriter, buildReportWriterContext(writerState), this.options.runner);
292	      state.portfolioAfter = execution.portfolio;
293	      state.appliedOrders = execution.orders;
294	      state.report = report;
295	      markStageComplete(state, "report_writer", isoAfter(decision.decidedAt, 2), report.id);
296	    } catch (error) {
297	      markStageFailed(state, "report_writer", isoAfter(decision.decidedAt, 2), errorMessage(error));
298	      return block(state, `report_writer failed: ${errorMessage(error)}`);
299	    }
300	
301	    if (decision.decision === "approved") {
302	      transition(state, "executing", "Human approved; applying deterministic paper-ledger actions.");
303	      appendActivity(state, {
304	        kind: "paper_trade",
305	        message: `Applied ${state.appliedOrders.length} paper orders after approval.`,
306	        refId: `rcpt_${state.run.id}`,
307	      });
308	    }
309	    const completedAt = isoAfter(decision.decidedAt, 3);
310	    state.run = { ...state.run, completedAt };
311	    const receiptId = `rcpt_${state.run.id}`;
312	    state.receipt = {
313	      id: receiptId,
314	      runId: state.run.id,
315	      createdAt: completedAt,
316	      event: state.materialEvents[0] ?? null,
317	      portfolioBefore: state.portfolioSnapshot,
318	      portfolioAfter: execution.portfolio,
319	      proposal: state.proposal,
320	      recommendation: state.finalRecommendation!,
321	      riskReport: state.riskReport!,
322	      bearCase: state.bearCase,
323	      userDecision: state.userDecision,
324	      appliedOrders: state.appliedOrders,
325	      report: state.report,
326	      evidence: state.evidence,
327	    };
328	    transition(state, "complete", decision.decision === "approved" ? "Decision receipt completed." : "Decision rejected; no paper actions applied.");
329	    return validateState(state);
330	  }
331	
332	  private async applyApprovedActions(state: InvestmentCommitteeState, appliedAt: string) {
333	    if (!state.finalRecommendation || !state.marketSnapshot) {
334	      throw new Error("Approved action requires final recommendation and market snapshot.");
335	    }
336	    if (state.riskReport?.hardBlocks.length) {
337	      throw new Error("Approved action cannot bypass deterministic risk hard block.");
338	    }
339	    if (!this.options.alpacaClient) return applyPaperActions({
340	      portfolio: state.portfolioSnapshot,
341	      actions: state.finalRecommendation.actions,
342	      marketSnapshot: state.marketSnapshot,
343	      appliedAt,
344	    });
345	
346	    if (state.portfolioSnapshot.baseCurrency !== "USD") {
347	      throw new Error("Alpaca Paper execution requires USD portfolio currency.");
348	    }
349	    const orderIds = new Map<string, string>();
350	    for (const action of state.finalRecommendation.actions) {
351	      const instrument = state.candidateUniverse.find((candidate) => candidate.id === action.instrumentId);
352	      if (!instrument) throw new Error(`Approved action references unknown instrument "${action.instrumentId}".`);
353	      const response = await this.options.alpacaClient.submitPaperOrder({
354	        symbol: instrument.symbol,
355	        notional: Math.abs(action.amount.amount),
356	        side: action.side,
357	        type: "market",
358	        time_in_force: "day",
359	        client_order_id: action.id,
360	      });
361	      if (response.symbol.toUpperCase() !== instrument.symbol.toUpperCase() || response.side !== action.side) {
362	        throw new Error(`Alpaca response mismatch for action "${action.id}".`);
363	      }
364	      orderIds.set(action.id, response.id);
365	    }
366	    return applyPaperActions({
367	      portfolio: state.portfolioSnapshot,
368	      actions: state.finalRecommendation.actions,
369	      marketSnapshot: state.marketSnapshot,
370	      appliedAt,
371	      orderIds,
372	    });
373	  }
374	}
375	
376	async function runAgent<TContext, TOutput>(
377	  definition: AgentDef<TContext, TOutput>,
378	  context: TContext,
379	  runner: AgentRunner,
380	): Promise<TOutput> {
381	  const result = await runner.run(definition, context);
382	  const parsed = definition.outputSchema.safeParse(result.output);
383	  if (!parsed.success) {
384	    throw new Error(`${definition.stage} output failed schema validation.`);
385	  }
386	  return parsed.data;
387	}
388	
389	async function runFinalizedAgent<TContext, TDraft, TOutput>(
390	  agent: Agent<TContext, TDraft, TOutput>,
391	  context: TContext,
392	  runner: AgentRunner,
393	): Promise<TOutput> {
394	  const draft = await runAgent(agent.def, context, runner);
395	  return agent.finalize(draft, context);
396	}
397	
398	function pendingStages(runId: string): StageRecord[] {
399	  return AGENT_STAGES.map((stage) => ({
400	    runId,
401	    stage,
402	    status: "pending",
403	    startedAt: null,
404	    completedAt: null,
405	    outputId: null,
406	  }));
407	}
408	
409	function markStageRunning(state: InvestmentCommitteeState, stage: AgentStage, startedAt: string): void {
410	  const record = stageRecord(state, stage);
411	  record.status = "running";
412	  record.startedAt = startedAt;
413	  record.completedAt = null;
414	  record.outputId = null;
415	}
416	
417	function markStageComplete(state: InvestmentCommitteeState, stage: AgentStage, completedAt: string, outputId: string | null): void {
418	  const record = stageRecord(state, stage);
419	  record.status = "complete";
420	  record.completedAt = completedAt;
421	  record.outputId = outputId;
422	}
423	
424	function markStageFailed(state: InvestmentCommitteeState, stage: AgentStage, completedAt: string, note: string): void {
425	  const record = stageRecord(state, stage);
426	  record.status = "failed";
427	  record.completedAt = completedAt;
428	  record.note = note;
429	}
430	
431	function stageRecord(state: InvestmentCommitteeState, stage: AgentStage): StageRecord {
432	  const record = state.stages.find((candidate) => candidate.stage === stage);
433	  if (!record) throw new Error(`Missing stage record for "${stage}".`);
434	  return record;
435	}
436	
437	function stageTime(state: InvestmentCommitteeState, stage: AgentStage, extraSeconds = 0): string {
438	  return isoAfter(state.run.startedAt, STAGE_OFFSETS[stage] + extraSeconds);
439	}
440	
441	function transition(state: InvestmentCommitteeState, next: InvestmentCommitteeState["phase"], message: string): void {
442	  if (state.phase !== next && !ALLOWED_TRANSITIONS[state.phase].includes(next)) {
443	    throw new Error(`Invalid phase transition "${state.phase}" -> "${next}".`);
444	  }
445	  state.phase = next;
446	  appendActivity(state, { kind: "phase_changed", message });
447	}
448	
449	function appendActivity(state: InvestmentCommitteeState, input: Omit<ActivityEvent, "id" | "at" | "evidenceIds"> & { evidenceIds?: string[] }): void {
450	  state.activities.push({
451	    id: `act_${state.activities.length + 1}`,
452	    at: state.run.startedAt,
453	    evidenceIds: input.evidenceIds ?? [],
454	    ...input,
455	  });
456	}
457	
458	function block(state: InvestmentCommitteeState, reason: string): InvestmentCommitteeState {
459	  for (const record of state.stages) {
460	    if (record.status === "pending" || record.status === "running") {
461	      record.status = "skipped";
462	      record.note = reason;
463	    }
464	  }
465	  if (state.phase !== "blocked") transition(state, "blocked", reason);
466	  return validateState(state);
467	}
468	
469	function validateState(state: InvestmentCommitteeState): InvestmentCommitteeState {
470	  return InvestmentCommitteeStateSchema.parse(state);
471	}
472	
473	function sameComparison(a: RiskReport, b: RiskReport): boolean {
474	  return JSON.stringify(a.comparison) === JSON.stringify(b.comparison);
475	}
476	
477	function isoAfter(value: string, seconds: number): string {
478	  return new Date(Date.parse(value) + seconds * 1000).toISOString();
479	}
480	
481	function errorMessage(error: unknown): string {
482	  return error instanceof Error ? error.message : String(error);
483	}
484	
485	function withEvidenceLedger(
486	  runner: AgentRunner,
487	  state: InvestmentCommitteeState,
488	): AgentRunner {
489	  return {
490	    async run<TContext, TOutput>(
491	      definition: AgentDef<TContext, TOutput>,
492	      context: TContext,
493	    ) {
494	      const result = await runner.run(definition, context);
495	      mergeEvidence(state.evidence, result.evidence ?? []);
496	      if (result.graph) mergeGraph(state.graph, result.graph);
497	      return result;
498	    },
499	  };
500	}
501	
502	function mergeGraph(
503	  target: InvestmentCommitteeState["graph"],
504	  additions: InvestmentCommitteeState["graph"],
505	): void {
506	  const nodes = new Map(target.nodes.map((item) => [item.id, item]));
507	  const edges = new Map(target.edges.map((item) => [item.id, item]));
508	  for (const item of additions.nodes) mergeGraphRecord(nodes, item);
509	  for (const item of additions.edges) mergeGraphRecord(edges, item);
510	  target.nodes = [...nodes.values()];
511	  target.edges = [...edges.values()];
512	}
513	
514	function mergeGraphRecord<T extends { id: string }>(target: Map<string, T>, item: T): void {
515	  const existing = target.get(item.id);
516	  if (existing && JSON.stringify(existing) !== JSON.stringify(item)) {
517	    throw new Error(`Conflicting graph record "${item.id}".`);
518	  }
519	  target.set(item.id, item);
520	}
521	
522	function mergeEvidence(target: Evidence[], additions: readonly Evidence[]): void {
523	  const byId = new Map(target.map((item) => [item.id, item]));
524	  for (const item of additions) {
525	    const existing = byId.get(item.id);
526	    if (existing && JSON.stringify(existing) !== JSON.stringify(item)) {
527	      throw new Error(`Conflicting evidence record "${item.id}".`);
528	    }
529	    if (!existing) {
530	      target.push(item);
531	      byId.set(item.id, item);
532	    }
533	  }
534	}
535

