const maxAttempts = this.options.maxRetries + 1;
let lastError: unknown;

for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
  try {
    return await requestStructuredOutput(this.options.client, {
      model: this.options.model,
      instructions: def.instructions,
      input,
      schema: def.outputSchema,
      schemaName: `sonar_${def.stage}`,
      maxOutputTokens: this.options.maxOutputTokens,
      toolNames: def.toolNames,
      toolRegistry: this.options.toolRegistry,
      toolContext: this.options.toolContext,
      maxToolCalls: this.options.maxToolCalls,
      maxToolOutputChars: this.options.maxToolOutputChars,
    });
  } catch (error) {
    lastError = error;
    if (attempt === maxAttempts) {
      const reason = error instanceof Error ? error.message : String(error);
      // Preserve the underlying cause so a timeout, an auth failure, or a
      // schema rejection is diagnosable instead of a generic "failed".
      throw new Error(
        `OpenAIAgentRunner: stage "${def.stage}" failed after ${maxAttempts} attempt(s): ${reason}`,
        { cause: lastError },
      );
    }
  }
}

