16	 * committee chooses the companies (Cala discovery) — the user never picks
17	 * tickers. A preset maps to the four deterministic mandate limits; `limits`
18	 * lets an advanced caller override individual limits, but it can only make the
19	 * mandate tighter or equal, never wider than the preset — a request can't widen
20	 * risk beyond what the preset allows.
21	 */
22	export const RiskPreferencesSchema = z.object({
23	  riskTolerance: z
24	    .enum(["conservative", "balanced", "aggressive"])
25	    .default("balanced"),
26	  /** Optional per-limit overrides. Clamped to be no wider than the preset. */
27	  limits: RiskLimitsSchema.partial().optional(),
28	}).strict();
29	export type RiskPreferences = z.infer<typeof RiskPreferencesSchema>;
30	
31	/**
32	 * Risk presets. `conservative` tightens every limit; `aggressive` loosens the
33	 * exposure/turnover ceilings and drops the cash floor. `balanced` is the demo
34	 * preset. None of these is investment advice — they are demo risk parameters.
35	 */
36	export const RISK_PRESET_LIMITS: Record<RiskPreferences["riskTolerance"], RiskLimits> = {
37	  conservative: {
38	    maxGrossExposurePerPosition: 0.15,
39	    maxSectorExposure: 0.3,
40	    minCashRatio: 0.25,
41	    maxTurnoverPerEvent: 0.1,
42	  },
43	  balanced: DEMO_RISK_LIMITS,
44	  aggressive: {
45	    maxGrossExposurePerPosition: 0.45,
46	    maxSectorExposure: 0.6,
47	    minCashRatio: 0.05,
48	    maxTurnoverPerEvent: 0.35,
49	  },
50	};
51	
52	/**
53	 * Resolve the effective mandate limits. Overrides may only TIGHTEN the preset:
54	 * exposure/turnover ceilings are capped at the preset (min), and the cash floor
55	 * is raised to at least the preset (max). This guarantees a caller can never
56	 * use `limits` to widen risk past the preset it selected.
57	 */
58	export function resolveRiskLimits(prefs: RiskPreferences): RiskLimits {
59	  const preset = RISK_PRESET_LIMITS[prefs.riskTolerance];
60	  const o = prefs.limits;
61	  if (!o) return preset;
62	  return RiskLimitsSchema.parse({
63	    maxGrossExposurePerPosition: Math.min(
64	      preset.maxGrossExposurePerPosition,
65	      o.maxGrossExposurePerPosition ?? preset.maxGrossExposurePerPosition,
66	    ),
67	    maxSectorExposure: Math.min(
68	      preset.maxSectorExposure,
69	      o.maxSectorExposure ?? preset.maxSectorExposure,
70	    ),
71	    minCashRatio: Math.max(preset.minCashRatio, o.minCashRatio ?? preset.minCashRatio),
72	    maxTurnoverPerEvent: Math.min(
73	      preset.maxTurnoverPerEvent,
74	      o.maxTurnoverPerEvent ?? preset.maxTurnoverPerEvent,
75	    ),
76	  });
77	}
