1	/**
2	 * Record one real committee run for the demo.
3	 *
4	 * The live flow makes several GPT-5 calls and can exceed the two-minute demo
5	 * window, so we capture a run ahead of time and replay it during the demo. This
6	 * script fires ONE real run and writes the transcript + final state to
7	 * apps/web/fixtures/runs/<runId>.json.
8	 *
9	 * Prerequisites (see apps/web/lib/server/runs/README.md):
10	 *   SONAR_OFFLINE=false  OPENAI_API_KEY=sk-...  [SONAR_AGENT_MODEL=gpt-5]
11	 *
12	 * Run from apps/web:  pnpm record:run
13	 */
14	import type { InvestmentCommitteeState } from "@sonar-ai/core";
15	// Demo input scenario. Swap for a dedicated fixtures/scenario once one exists;
16	// for now the core golden fixture supplies a realistic idle state + evidence.
17	import { goldenState } from "../../../packages/core/src/__fixtures__/golden-state";
18	import { createOpenAIAgentRunner } from "../lib/server/analysis/runner/openai-runner";
19	import { getServerEnv } from "../lib/server/env";
20	import { recordCommitteeRun, saveRecording } from "../lib/server/runs/record";
21	import { resetToIdle } from "../lib/server/runs/recording";
22	
23	async function main(): Promise<void> {
24	  // A standalone `tsx` process does NOT auto-load .env the way `next dev` does,
25	  // so load it here before reading the environment. Node >= 20.12 built-in; no
26	  // dependency. Missing file is fine — fall back to the real environment.
27	  try {
28	    process.loadEnvFile();
29	  } catch {
30	    // No .env in cwd; rely on already-exported environment variables.
31	  }
32	
33	  const env = getServerEnv();
34	  if (env.SONAR_OFFLINE) {
35	    console.error(
36	      "SONAR_OFFLINE=true — a real run is disabled. Set SONAR_OFFLINE=false and OPENAI_API_KEY, then re-run.",
37	    );
38	    process.exit(1);
39	  }
40	
41	  const runner = createOpenAIAgentRunner(env);
42	  console.error(`Recording a live run with model "${env.SONAR_AGENT_MODEL}"...`);
43	
44	  const recording = await recordCommitteeRun({
45	    state: resetToIdle(goldenState as InvestmentCommitteeState),
46	    userDecision: {
47	      decision: "approved",
48	      decidedAt: new Date().toISOString(),
49	      note: "Recorded demo run.",
50	    },
51	    runner,
52	    model: env.SONAR_AGENT_MODEL,
53	    instrumentStats: {
54	      inst_nvidia: { volatility: 0.2, beta: 1.4 },
55	      inst_siemens: { volatility: 0.1, beta: 0.9 },
56	    },
57	    stressScenarios: [{ name: "AI capex slowdown", marketShock: -0.2 }],
58	  });
59	
60	  const inputTokens = recording.turns.reduce((n, t) => n + (t.usage?.inputTokens ?? 0), 0);
61	  const outputTokens = recording.turns.reduce((n, t) => n + (t.usage?.outputTokens ?? 0), 0);
62	
63	  // Never save a blocked/empty run: it would poison the offline replay path
64	  // (an empty stub blocks every future offline run). Report the failure instead.
65	  if (recording.state.phase === "blocked" || recording.turns.length === 0) {
66	    const failed = recording.state.stages.find((stage) => stage.status === "failed");
67	    console.error(
68	      `Run BLOCKED — not saved. ${recording.turns.length} turns, tokens in/out=${inputTokens}/${outputTokens}.\n` +
69	        `Cause: ${failed?.note ?? "see the [OpenAIAgentRunner]/[CalaClient] logs above."}`,
70	    );
71	    process.exit(1);
72	  }
73	
74	  const path = await saveRecording(recording);
75	  console.error(
76	    `Saved ${recording.turns.length} agent turns to ${path}\n` +
77	      `phase=${recording.state.phase}  tokens in/out=${inputTokens}/${outputTokens}`,
78	  );
79	}
80	
81	main().catch((error) => {
82	  console.error(error instanceof Error ? error.message : String(error));
83	  process.exit(1);
84	});
85

